(()=>{document.querySelectorAll('[data-load-board]').forEach(button=>button.addEventListener('click',()=>{const wrapper=button.closest('.board-exhibit');const frame=document.createElement('iframe');frame.src=button.dataset.loadBoard;frame.title='地瓜丸 FPGA 教学平台 3D 硬件桌面';frame.allow='fullscreen';frame.loading='eager';wrapper.replaceChildren(frame);wrapper.classList.add('loaded')}));document.querySelectorAll('img[data-local-fallback]').forEach(img=>{img.addEventListener('error',()=>{const p=img.closest('picture');if(p)p.querySelectorAll('source').forEach(s=>s.remove());const local=img.dataset.localFallback;delete img.dataset.localFallback;img.src=local},{once:true})})})();